//! `seq` — GNU coreutils seq.c (9.4) semantics, ported from the source and
//! probed byte-for-byte against WSL coreutils 9.4.
//!
//! Two generation paths, exactly like seq.c:
//!
//! * Fast integer path (`seq_fast`): when the operand pattern is all digit
//!   strings (1/2 args, or 3 args whose step is an all-digit string in
//!   1..=200), no -w/-f was given and the separator is exactly one byte,
//!   numbers are generated by decimal string increment — arbitrarily large
//!   integers print exactly (GNU probed: `seq 100000000000000000000
//!   100000000000000000100` steps by 1). Leading zeros are trimmed; if the
//!   trimmed end is smaller than the trimmed start, nothing prints (GNU
//!   then falls through to the long-double path, which also prints
//!   nothing). `inf` as the end value loops forever (GNU does too; SIGPIPE
//!   ends it there, a write error ends it here).
//! * Exact-decimal path (borrowed from the uutils seq algorithm, #1488
//!   borrow-algo): when no -f was given and every operand is a finite
//!   fixed-point decimal, operands parse as (integer mantissa, decimal
//!   scale) pairs and the loop steps in the scaled-integer domain
//!   (std-only, i128, checked — anything that does not fit falls back to
//!   the float path). The default format there is `%.<prec>f` / `%0<w>.<prec>f`
//!   (`seq.c get_default_format`, lines 373-406), and an exact decimal
//!   rendered at prec digits is the byte-identical printf output while the
//!   scaled values stay inside GNU's long-double mantissa (WSL GNU 9.4
//!   probed: the audit case `0.9999999999999999999 1.0000000000000000002`
//!   and the sub-ulp `0.9999999999999999999 1e-19 1.0000000000000000002`).
//!   GNU's rounding fixup (print_numbers lines 340-356) only repairs long
//!   double rounding and is dead here: the value just past LAST sits on the
//!   10^-prec grid, so its exact rendering never reparses to LAST. Past the
//!   long-double mantissa GNU itself prints float artifacts (probed:
//!   `2 1e-19 2.0000000000000000005` duplicates lines; `-1.5 0.9999999999999999999
//!   1.5` drifts a final ulp) — those shapes keep exact output, a
//!   documented divergence from GNU's broken bytes.
//! * Long-double path: operands parsed as floats (f64 here; GNU uses
//!   80-bit long double, so >16-significant-digit float inputs may round
//!   differently — documented divergence). Default format is `%.<prec>f`
//!   where prec is the maximum fraction-digit count over first/step (when
//!   every operand is a fixed-point decimal), else `%g`. `-w` zero-pads to
//!   the width scan_arg() derives from the operand texts (seq.c's width
//!   arithmetic is ported line-for-line). The print_numbers() loop
//!   computes `first + i*step` and, when the value just past LAST formats
//!   back equal to LAST but prints differently from the previous number,
//!   prints it (the `seq 0 0.000001 0.000003` rule).
//!
//! Option parsing mirrors seq.c's loop: options stop at the first
//! non-option and at any operand starting with `-.` or `-/digit` (negative
//! numbers), so `--` after the first operand is a plain operand. Error
//! order matches seq.c main(): missing/extra operand, then format
//! validation, then the -w/-f conflict, then operand scan errors.
//! All error exits are rc 1.

use std::ffi::OsString;

use winux_core::{usage_error, CmdResult, Ctx, Io};

const SEQ_FAST_STEP_LIMIT: u64 = 200;
/// Sane cap for printf widths so a bogus `%999999999999f` cannot OOM us;
/// genuine widths (operand-text derived) never approach this.
const MAX_FORMAT_WIDTH: usize = 1 << 20;

/// One command-line operand (seq.c `struct operand`).
#[derive(Clone, Copy)]
struct Operand {
    value: f64,
    /// Print width as if printed like the input form ("-.1" -> "-0.1").
    width: isize,
    /// Digits after the decimal point, or usize::MAX when not fixed point.
    precision: usize,
}

const NOT_FIXED: usize = usize::MAX;

/// Parse a float the way strtold-in-C-locale does: optional leading
/// whitespace and sign, then decimal / hex-float / inf / nan. The whole
/// string must be consumed. Returns None on any trailing garbage.
fn strtold_full(s: &str) -> Option<f64> {
    let t = s.trim_start_matches(|c: char| c.is_ascii_whitespace());
    let neg = t.starts_with('-');
    let rest = t.strip_prefix(['+', '-']).unwrap_or(t);
    let low = rest.to_ascii_lowercase();
    match low.as_str() {
        "inf" | "infinity" => {
            return Some(if neg {
                f64::NEG_INFINITY
            } else {
                f64::INFINITY
            });
        }
        _ => {}
    }
    if low == "nan" || low.starts_with("nan(") {
        if let Some(payload) = low.strip_prefix("nan(") {
            if !payload.ends_with(')') {
                return None;
            }
        }
        return Some(f64::NAN);
    }
    if rest.len() >= 2 && (rest.starts_with("0x") || rest.starts_with("0X")) {
        let v = parse_hex_float(rest)?;
        return Some(if neg { -v } else { v });
    }
    // Decimal must consume the whole string: f64::from_str accepts the
    // sign, "1.", ".5", "1e3" — the same grammar strtold uses.
    t.parse::<f64>().ok()
}

/// Parse a C99 hex float: 0x hexdigits [. hexdigits] [p [sign] decimals].
fn parse_hex_float(s: &str) -> Option<f64> {
    let body = &s[2..];
    let lower = body.to_ascii_lowercase();
    let (mant_str, exp) = match lower.split_once('p') {
        Some((m, e)) => (m, e.parse::<i32>().ok()),
        None => (lower.as_str(), Some(0)),
    };
    let (int_part, frac_part) = match mant_str.split_once('.') {
        Some((i, f)) => (i, f),
        None => (mant_str, ""),
    };
    if int_part.is_empty() && frac_part.is_empty() {
        return None;
    }
    let mut value = 0f64;
    for c in int_part.chars() {
        let d = c.to_digit(16)? as f64;
        value = value * 16.0 + d;
    }
    let mut scale = 1.0 / 16.0;
    for c in frac_part.chars() {
        let d = c.to_digit(16)? as f64;
        value += d * scale;
        scale /= 16.0;
    }
    Some(value * (2f64).powi(exp?))
}

/// scan_arg(): value plus the auto width/precision of the input form,
/// ported from seq.c lines 146-226.
fn scan_arg(arg: &str) -> Result<Operand, ()> {
    let value = strtold_full(arg).ok_or(())?;
    // seq.c: skip leading whitespace and '+' before measuring the text.
    let mut text = arg;
    while text.starts_with(|c: char| c.is_ascii_whitespace()) || text.starts_with('+') {
        text = &text[1..];
    }
    let mut width: isize = 0;
    let mut precision: usize = NOT_FIXED;
    let decimal_point = text.find('.');
    if decimal_point.is_none() && !text.contains('p') {
        precision = 0;
    }
    if !text.contains(['x', 'X']) && value.is_finite() {
        width = text.len() as isize;
        if let Some(dp) = decimal_point {
            let after = &text[dp + 1..];
            let fraction_len = after.find(['e', 'E']).unwrap_or(after.len());
            if fraction_len != 0 {
                precision = fraction_len;
            }
            width += if fraction_len == 0 {
                -1isize // "#." prints as "#"
            } else if dp == 0 || !text.as_bytes()[dp - 1].is_ascii_digit() {
                1isize // ".#" or "-.#" print with a leading 0
            } else {
                0isize
            };
        }
        let e = text.find('e').or_else(|| text.find('E'));
        if let Some(e) = e {
            let mut exponent: isize = text[e + 1..].parse().map_err(|_| ())?;
            precision = precision.saturating_add_signed(if exponent < 0 {
                -exponent
            } else {
                -(precision.min(exponent as usize) as isize)
            });
            // width does not account for the "e..." tail
            width -= (text.len() - e) as isize;
            if exponent < 0 {
                if let Some(dp) = decimal_point {
                    if e == dp + 1 {
                        // undo the "#. -> #" discount above
                        width += 1;
                    }
                } else {
                    width += 1;
                }
                exponent = -exponent;
            } else {
                let frac_len = decimal_point
                    .map(|dp| {
                        let after = &text[dp + 1..];
                        after.find(['e', 'E']).unwrap_or(after.len())
                    })
                    .unwrap_or(0);
                if decimal_point.is_some() && precision == 0 && frac_len > 0 {
                    width -= 1; // discount space for '.'
                }
                exponent -= frac_len.min(exponent as usize) as isize;
            }
            width += exponent;
        }
    }
    Ok(Operand {
        value,
        width,
        precision,
    })
}

/// C-printf-shaped parsed format (the flags seq.c passes through).
#[derive(Default, Clone)]
struct FormatSpec {
    left_adjust: bool,
    plus: bool,
    space: bool,
    zero_pad: bool,
    alternate: bool,
    width: usize,
    precision: Option<usize>,
}

fn pad_width(mut s: String, spec: &FormatSpec) -> String {
    let w = spec.width;
    if s.len() >= w {
        return s;
    }
    let insert = w - s.len();
    if spec.left_adjust {
        s.push_str(&" ".repeat(insert));
        return s;
    }
    if spec.zero_pad {
        let signed = s.starts_with(['-', '+']) || s.starts_with(' ');
        if signed {
            let sign = s.remove(0);
            return format!("{sign}{}{s}", "0".repeat(insert));
        }
        return format!("{}{s}", "0".repeat(insert));
    }
    format!("{}{s}", " ".repeat(insert))
}

fn sign_prefix(x: f64, spec: &FormatSpec) -> &'static str {
    if x < 0.0 || (x == 0.0 && x.is_sign_negative()) || x.is_negative_infinity() {
        "-"
    } else if spec.plus {
        "+"
    } else if spec.space {
        " "
    } else {
        ""
    }
}

trait NegInf {
    fn is_negative_infinity(&self) -> bool;
}
impl NegInf for f64 {
    fn is_negative_infinity(&self) -> bool {
        *self == f64::NEG_INFINITY
    }
}

/// C printf %g semantics (flags/width/precision support).
fn format_g(x: f64, spec: &FormatSpec, upper: bool) -> String {
    if !x.is_finite() {
        return if x.is_nan() {
            if x.is_sign_negative() {
                "-nan".to_string()
            } else {
                "nan".to_string()
            }
        } else if x.is_negative_infinity() {
            "-inf".to_string()
        } else {
            "inf".to_string()
        };
    }
    let mut p = spec.precision.unwrap_or(6);
    if p == 0 {
        p = 1;
    }
    let body = format!("{:.*e}", p - 1, x);
    let epos = body.find('e').unwrap();
    let mantissa = &body[..epos];
    let exp: i32 = body[epos + 1..].parse().unwrap();
    if exp < -4 || exp >= p as i32 {
        let m = if spec.alternate {
            mantissa.to_string()
        } else {
            mantissa
                .trim_end_matches('0')
                .trim_end_matches('.')
                .to_string()
        };
        let e = if upper { 'E' } else { 'e' };
        format!("{m}{e}{}{:02}", if exp < 0 { "-" } else { "+" }, exp.abs())
    } else {
        let dec = (p as i32 - 1 - exp).max(0) as usize;
        let mut s = format!("{:.*}", dec, x);
        if !spec.alternate && s.contains('.') {
            s = s.trim_end_matches('0').trim_end_matches('.').to_string();
        }
        s
    }
}

/// C printf %e semantics with C-style exponent.
fn format_e(x: f64, spec: &FormatSpec, upper: bool) -> String {
    if !x.is_finite() {
        return if x.is_nan() {
            if x.is_sign_negative() {
                "-nan".to_string()
            } else {
                "nan".to_string()
            }
        } else if x.is_negative_infinity() {
            "-inf".to_string()
        } else {
            "inf".to_string()
        };
    }
    let p = spec.precision.unwrap_or(6);
    let body = format!("{:.*e}", p, x);
    let epos = body.find('e').unwrap();
    let mantissa = &body[..epos];
    let exp: i32 = body[epos + 1..].parse().unwrap();
    let e = if upper { 'E' } else { 'e' };
    format!(
        "{mantissa}{e}{}{:02}",
        if exp < 0 { "-" } else { "+" },
        exp.abs()
    )
}

fn format_f(x: f64, spec: &FormatSpec) -> String {
    let p = spec.precision.unwrap_or(6);
    let mut body = if x.is_finite() {
        format!("{:.*}", p, x)
    } else if x.is_nan() {
        if x.is_sign_negative() {
            "-nan".to_string()
        } else {
            "nan".to_string()
        }
    } else if x.is_negative_infinity() {
        "-inf".to_string()
    } else {
        "inf".to_string()
    };
    if spec.alternate && x.is_finite() && !body.contains('.') {
        body.push('.');
    }
    body
}

/// glibc-style %a/%A: value = d * 2^hex_exp with 8 <= d < 16 (glibc shifts
/// the mantissa so the leading hex digit is 8..f; GNU probed 1 -> "0x8p-3",
/// 1.5 -> "0xCp-3", 2.5 -> "0xAp-2", %A uppercase).
fn format_hex_float(x: f64, spec: &FormatSpec, upper: bool) -> String {
    if x.is_nan() {
        return if x.is_sign_negative() {
            "-nan".to_string()
        } else {
            "nan".to_string()
        };
    }
    if !x.is_finite() {
        return if x.is_negative_infinity() {
            "-inf".to_string()
        } else {
            "inf".to_string()
        };
    }
    let explicit_prec = spec.precision;
    let v = x.abs();
    if v == 0.0 {
        let head = if upper { "0X0" } else { "0x0" };
        let frac = match explicit_prec {
            Some(p) if p > 0 => format!(".{}", "0".repeat(p)),
            Some(_) => ".".to_string(),
            None => String::new(),
        };
        return format!("{head}{frac}p+0");
    }
    let e = v.log2().floor() as i32;
    let mut mant = v / (2f64).powi(e) * 8.0; // [8, 16)
    let mut hex_exp = e - 3;
    let p = explicit_prec.unwrap_or(13);
    if p < 13 {
        let scale = 16f64.powi(p as i32);
        mant = (mant * scale).round() / scale;
        if mant >= 16.0 {
            mant /= 16.0;
            hex_exp += 4;
        }
    }
    // decimal digits of mant, p fraction digits
    let lead = mant.floor() as u32;
    let mut frac_mant = mant - lead as f64;
    let mut frac = String::new();
    for _ in 0..p {
        frac_mant *= 16.0;
        let d = (frac_mant.floor() as u32).min(15);
        frac.push(std::char::from_digit(d, 16).unwrap());
        frac_mant -= d as f64;
    }
    let frac = if explicit_prec.is_none() {
        let t = frac.trim_end_matches('0');
        if t.is_empty() {
            String::new()
        } else {
            format!(".{t}")
        }
    } else if p == 0 {
        if spec.alternate {
            ".".to_string()
        } else {
            String::new()
        }
    } else {
        format!(".{frac}")
    };
    let (hx, ec) = if upper { ("0X", 'P') } else { ("0x", 'p') };
    let lead_digit = std::char::from_digit(lead, 16).unwrap_or('0');
    let lead_digit = if upper {
        lead_digit.to_ascii_uppercase()
    } else {
        lead_digit
    };
    format!(
        "{}{}{}{frac}{}{}{}",
        sign_prefix(x, spec),
        hx,
        lead_digit,
        ec,
        if hex_exp < 0 { "-" } else { "+" },
        hex_exp.abs()
    )
}

/// long_double_format(): validate a seq format and split it at the single
/// % directive. Returns (prefix, spec, conversion, suffix).
fn parse_format(fmt: &str) -> Result<(String, FormatSpec, char, String), String> {
    let bytes = fmt.as_bytes();
    let mut i = 0usize;
    let prefix_len;
    loop {
        if i >= bytes.len() {
            return Err(format!("format '{fmt}' has no % directive"));
        }
        if bytes[i] == b'%' {
            if i + 1 < bytes.len() && bytes[i + 1] == b'%' {
                i += 2;
                continue;
            }
            break;
        }
        i += 1;
    }
    prefix_len = i;
    i += 1;
    let mut spec = FormatSpec::default();
    while i < bytes.len() && matches!(bytes[i], b'-' | b'+' | b'#' | b'0' | b' ' | b'\'') {
        match bytes[i] {
            b'-' => spec.left_adjust = true,
            b'+' => spec.plus = true,
            b'#' => spec.alternate = true,
            b'0' => spec.zero_pad = true,
            b' ' => spec.space = true,
            _ => {}
        }
        i += 1;
    }
    let wstart = i;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
    }
    if i > wstart {
        spec.width = fmt[wstart..i]
            .parse::<usize>()
            .unwrap_or(MAX_FORMAT_WIDTH)
            .min(MAX_FORMAT_WIDTH);
    }
    if i < bytes.len() && bytes[i] == b'.' {
        i += 1;
        let pstart = i;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
        spec.precision = if i > pstart {
            Some(
                fmt[pstart..i]
                    .parse::<usize>()
                    .unwrap_or(MAX_FORMAT_WIDTH)
                    .min(MAX_FORMAT_WIDTH),
            )
        } else {
            Some(0)
        };
    }
    if i < bytes.len() && bytes[i] == b'L' {
        i += 1;
    }
    if i >= bytes.len() {
        return Err(format!("format '{fmt}' ends in %"));
    }
    let conv = fmt[i..].chars().next().unwrap();
    if !"efgaEFGA".contains(conv) {
        return Err(format!("format '{fmt}' has unknown %{conv} directive"));
    }
    i += conv.len_utf8();
    let mut suffix = String::new();
    let mut j = i;
    while j < bytes.len() {
        if bytes[j] == b'%' {
            if j + 1 < bytes.len() && bytes[j + 1] == b'%' {
                suffix.push('%');
                j += 2;
                continue;
            }
            return Err(format!("format '{fmt}' has too many % directives"));
        }
        let c = fmt[j..].chars().next().unwrap();
        suffix.push(c);
        j += c.len_utf8();
    }
    Ok((fmt[..prefix_len].to_string(), spec, conv, suffix))
}

fn spec_render(x: f64, spec: &FormatSpec, conv: char) -> String {
    let raw = match conv {
        'e' => format_e(x, spec, false),
        'E' => format_e(x, spec, true),
        'f' | 'F' => format_f(x, spec),
        'g' => format_g(x, spec, false),
        'G' => format_g(x, spec, true),
        'a' => return pad_width(format_hex_float(x, spec, false), spec),
        'A' => return pad_width(format_hex_float(x, spec, true), spec),
        _ => String::new(),
    };
    // C printf: '+ '/' ' flags only affect non-negative values; the body
    // already carries '-' for negatives (and -nan/-inf).
    let mut s = raw;
    if x >= 0.0 && !s.starts_with('-') {
        if spec.plus {
            s.insert(0, '+');
        } else if spec.space {
            s.insert(0, ' ');
        }
    }
    pad_width(s, spec)
}

fn default_format(first: &Operand, step: &Operand, last: &Operand, equal_width: bool) -> String {
    let prec = first.precision.max(step.precision);
    if prec != NOT_FIXED && last.precision != NOT_FIXED {
        if equal_width {
            let mut first_width = first.width;
            if prec > first.precision {
                first_width += (prec - first.precision) as isize;
            }
            let mut last_width = last.width;
            if prec > last.precision {
                last_width += (prec - last.precision) as isize;
            }
            if last.precision > 0 && prec == 0 {
                last_width -= 1; // don't include space for '.'
            }
            if last.precision == 0 && prec > 0 {
                last_width += 1; // include space for '.'
            }
            if first.precision == 0 && prec > 0 {
                first_width += 1; // include space for '.'
            }
            let width = first_width.max(last_width).max(0) as usize;
            return format!("%0{width}.{prec}f");
        }
        return format!("%.{prec}f");
    }
    "%g".to_string()
}

/// Exact fixed-point decimal (uutils-borrowed): value = mant * 10^-scale.
/// std-only — i128 with checked arithmetic; anything that does not fit
/// sends the case back to the float path (documented divergence there).
struct ExactDec {
    mant: i128,
    scale: u32,
    /// The text carried a signed zero ("-0", "-0.0"); printf shows the
    /// sign on the rendered zero, so it must survive normalization.
    neg_zero: bool,
}

/// Fraction-digit cap for the exact domain. 64 covers every value whose
/// scaled mantissa could still fit i128 headroom; beyond it the widen()
/// step would bail anyway, and huge-scale tiny-magnitude inputs would
/// render gigabyte fraction strings.
const EXACT_MAX_SCALE: u32 = 64;

/// Parse a finite fixed-point decimal: [ws][sign]digits[.digits][eE[sign]digits],
/// the whole string consumed. Hex floats / inf / nan return None (those
/// are not fixed-point and keep the float path).
fn parse_exact_decimal(s: &str) -> Option<ExactDec> {
    let t = s.trim_start_matches(|c: char| c.is_ascii_whitespace());
    let neg = t.starts_with('-');
    let rest = t.strip_prefix(['+', '-']).unwrap_or(t);
    if rest.is_empty() {
        return None;
    }
    let low = rest.to_ascii_lowercase();
    if low.starts_with("0x")
        || low == "inf"
        || low == "infinity"
        || low == "nan"
        || low.starts_with("nan(")
    {
        return None;
    }
    let (mant_str, exp) = match low.split_once('e') {
        Some((m, e)) => (m, e.parse::<i32>().ok()?),
        None => (low.as_str(), 0i32),
    };
    let (int_part, frac_part) = match mant_str.split_once('.') {
        Some((i, f)) => (i, f),
        None => (mant_str, ""),
    };
    if (int_part.is_empty() && frac_part.is_empty())
        || !int_part.bytes().all(|b| b.is_ascii_digit())
        || !frac_part.bytes().all(|b| b.is_ascii_digit())
    {
        return None;
    }
    let mut mag: u128 = 0;
    for b in int_part.bytes().chain(frac_part.bytes()) {
        mag = mag.checked_mul(10)?.checked_add(u128::from(b - b'0'))?;
    }
    let n = exp - frac_part.len() as i32;
    let mut scale: u32 = if n < 0 {
        u32::try_from(-n).ok()?
    } else {
        for _ in 0..n {
            mag = mag.checked_mul(10)?;
        }
        0
    };
    if scale > EXACT_MAX_SCALE {
        return None;
    }
    // drop redundant trailing zeros so the common-scale widen stays small
    while scale > 0 && mag % 10 == 0 {
        mag /= 10;
        scale -= 1;
    }
    if mag > i128::MAX as u128 {
        return None;
    }
    let mant = if neg { -(mag as i128) } else { mag as i128 };
    Some(ExactDec {
        mant,
        scale,
        neg_zero: neg && mag == 0,
    })
}

/// One prepared exact sequence: first/step on the 10^-prec rendering
/// grid, last as the exact loop bound (multiplied by `bound_mul` for
/// comparison when the last operand's scale is finer than prec), with -w
/// width lifted from the default format.
struct ExactRun {
    first: i128,
    step: i128,
    last: i128,
    /// Scale-up factor for bound comparisons against `last` (1 when last
    /// sits on the same 10^-prec grid as first/step).
    bound_mul: i128,
    prec: usize,
    zero_width: usize,
    first_neg_zero: bool,
}

/// Build the exact run when the case qualifies: default format only, all
/// three operands fixed-point decimals whose common-scale mantissas fit.
fn try_exact_run(
    texts: (&str, &str, &str),
    first_scan: &Operand,
    step_scan: &Operand,
    last_scan: &Operand,
    equal_width: bool,
) -> Option<ExactRun> {
    // The default format is %.<prec>f / %0<w>.<prec>f only when every
    // operand is fixed point (get_default_format); otherwise it is %g and
    // the float path keeps the case.
    if first_scan.precision == NOT_FIXED
        || step_scan.precision == NOT_FIXED
        || last_scan.precision == NOT_FIXED
    {
        return None;
    }
    let f = parse_exact_decimal(texts.0)?;
    let s = parse_exact_decimal(texts.1)?;
    let l = parse_exact_decimal(texts.2)?;
    let prec = first_scan.precision.max(step_scan.precision);
    // exact rendering: first and step must lie on the 10^-prec grid
    if f.scale as usize > prec || s.scale as usize > prec {
        return None;
    }
    let t = f.scale.max(s.scale).max(l.scale);
    let widen = |d: &ExactDec| -> Option<i128> {
        let mut m = d.mant;
        for _ in 0..(t - d.scale) {
            m = m.checked_mul(10)?;
        }
        Some(m)
    };
    let fm = widen(&f)?;
    let sm = widen(&s)?;
    let lm = widen(&l)?;
    // Parity guard: GNU renders the long-double values (seq.c print_numbers),
    // so the exact digits stay byte-identical only while every magnitude the
    // long-double arithmetic touches stays below the 64-bit mantissa grid —
    // < 2^64 units of 10^-prec (~19 significant digits). Probed boundary
    // (WSL GNU 9.4): 0.9999999999999999999 (9.99e18 units) is exact, but
    // 0.99999999999999999999 (9.99e19 units) parses in long double to 1.0
    // and GNU prints 1.00000000000000000000 — that shape keeps the float
    // path, which rounds the same way.
    let grid = 18_446_744_073_709_551_616u128; // 2^64
                                               // magnitude measured in 10^-prec units (a normalized zero has scale 0
                                               // while its scan precision keeps the fraction digits, so prec > t is
                                               // possible and scales magnitudes up instead of down)
    let in_prec_units = |m: u128| -> Option<u128> {
        if t >= prec as u32 {
            Some(m / u128::checked_pow(10, t - prec as u32)?)
        } else {
            m.checked_mul(u128::checked_pow(10, prec as u32 - t)?)
        }
    };
    let in_ld_grid = |m: u128| -> bool { in_prec_units(m).map_or(false, |v| v <= grid) };
    if !in_ld_grid(fm.unsigned_abs())
        || !in_ld_grid(lm.unsigned_abs())
        || !in_ld_grid(fm.abs_diff(lm))
    {
        return None;
    }
    // lift first/step/last onto the rendering grid (prec) so every value
    // the loop touches carries exactly the digits render_exact prints
    // (e.g. `seq 0.0 3`: all integers, scan precision 1 -> 10, 30 on the
    // 10^-1 grid)
    let mut fm = fm;
    let mut sm = sm;
    let mut lm = lm;
    if t < prec as u32 {
        let Some(up) = i128::checked_pow(10, prec as u32 - t) else {
            return None;
        };
        fm = fm.checked_mul(up)?;
        sm = sm.checked_mul(up)?;
        lm = lm.checked_mul(up)?;
    }
    // [t > prec] the last operand may carry finer fraction digits than
    // the rendering precision (prec = max(first, step) per GNU
    // get_default_format). first and step stay exactly on the 10^-prec
    // grid — their widen to the common scale only appended zeros — so
    // drop them onto it and keep last on its native 10^-t grid, scaling
    // the bound comparisons back up by 10^(t-prec). Rendering the t-grid
    // mantissas on the prec grid instead printed every value 10^(t-prec)
    // times its real size (`seq 0.5 1.55` printed "5.0\n15.0" where GNU
    // prints "0.5\n1.5"; found by seq.seq_precision_ignores_last_operand,
    // the #1575 borrow-algo wiring).
    let bound_mul: i128 = if t > prec as u32 {
        let Some(m) = i128::checked_pow(10, t - prec as u32) else {
            return None;
        };
        let mu = m.unsigned_abs();
        let drop = |v: i128| -> Option<i128> {
            // exact by construction: widen appended these zeros
            (v.unsigned_abs() % mu == 0).then(|| v / m)
        };
        fm = drop(fm)?;
        sm = drop(sm)?;
        m
    } else {
        1
    };
    let zero_width = if equal_width {
        // same width derivation as get_default_format via the scanned
        // operand texts; the emitted default is %0<w>.<prec>f
        let fmt = default_format(first_scan, step_scan, last_scan, true);
        let (_, spec, conv, _) = parse_format(&fmt).ok()?;
        if conv != 'f' {
            return None;
        }
        if spec.zero_pad {
            spec.width
        } else {
            0
        }
    } else {
        0
    };
    Some(ExactRun {
        first: fm,
        step: sm,
        last: lm,
        bound_mul,
        prec,
        zero_width,
        first_neg_zero: f.neg_zero,
    })
}

/// Render a value already on the 10^-prec grid: exact decimal digits (the
/// printf %.<prec>f output for that value), zero-padded like %0<w>.<prec>f
/// with the zeros inserted after the sign.
fn render_exact(mag: u128, neg: bool, prec: usize, zero_width: usize) -> String {
    let digits = mag.to_string();
    let mut body = String::new();
    if neg {
        body.push('-');
    }
    if digits.len() > prec {
        body.push_str(&digits[..digits.len() - prec]);
        if prec > 0 {
            body.push('.');
            body.push_str(&digits[digits.len() - prec..]);
        }
    } else {
        body.push('0');
        if prec > 0 {
            body.push('.');
            body.push_str(&"0".repeat(prec - digits.len()));
            body.push_str(&digits);
        }
    }
    if body.len() < zero_width {
        let zeros = "0".repeat(zero_width - body.len());
        if neg {
            body.insert_str(1, &zeros);
        } else {
            body.insert_str(0, &zeros);
        }
    }
    body
}

impl ExactRun {
    /// print_numbers() in the exact domain (seq.c lines 300-364): print
    /// while first + i*step <= LAST, nothing at all when LAST is behind
    /// FIRST. The rounding fixup (lines 340-356) repairs long-double
    /// rounding and is dead here — see the module comment.
    fn print(&self, io: &mut Io, separator: &str) -> std::io::Result<()> {
        let neg_step = self.step < 0;
        let mut out_of_range = if neg_step {
            self.first.saturating_mul(self.bound_mul) < self.last
        } else {
            self.last < self.first.saturating_mul(self.bound_mul)
        };
        if out_of_range {
            return Ok(());
        }
        let neg_first = self.first < 0 || (self.first == 0 && self.first_neg_zero);
        let mut cur = self.first;
        let mut at_first = true;
        loop {
            let neg = if at_first { neg_first } else { cur < 0 };
            let body = render_exact(cur.unsigned_abs(), neg, self.prec, self.zero_width);
            io.stdout.write_all(body.as_bytes())?;
            if out_of_range {
                break;
            }
            // cur + step beyond i128 is beyond LAST too (LAST fits), so the
            // loop ends there exactly as the range check would
            let next = match cur.checked_add(self.step) {
                Some(v) => v,
                None => break,
            };
            // saturating: the true product never lands between the
            // saturated i128 extreme and the bound, so every comparison
            // resolves the way the real value would
            let scaled = next.saturating_mul(self.bound_mul);
            out_of_range = if neg_step {
                scaled < self.last
            } else {
                scaled > self.last
            };
            if out_of_range {
                break;
            }
            io.stdout.write_all(separator.as_bytes())?;
            cur = next;
            at_first = false;
        }
        io.stdout.write_all(b"\n")
    }
}

/// print_numbers(): the long-double generation loop (seq.c lines 291-359).
fn print_numbers(
    io: &mut Io,
    spec: &FormatSpec,
    conv: char,
    prefix: &str,
    suffix: &str,
    first: f64,
    step: f64,
    last: f64,
    separator: &str,
) -> std::io::Result<()> {
    let mut out_of_range = if step < 0.0 {
        first < last
    } else {
        last < first
    };
    if out_of_range {
        return Ok(());
    }
    let mut x = first;
    let mut i = 1f64;
    loop {
        let x0 = x;
        let body = spec_render(x, spec, conv);
        io.stdout.write_all(prefix.as_bytes())?;
        io.stdout.write_all(body.as_bytes())?;
        io.stdout.write_all(suffix.as_bytes())?;
        if out_of_range {
            break;
        }
        x = first + i * step;
        out_of_range = if step < 0.0 { x < last } else { last < x };
        if out_of_range {
            // The number just past LAST: if it formats back to exactly
            // LAST but prints differently from the previous number,
            // print it (seq.c's rounding fixup, lines 312-350).
            let mut print_extra = false;
            let body = spec_render(x, spec, conv);
            if let Some(x_val) = strtold_full(&body) {
                if x_val == last {
                    let x0_body = spec_render(x0, spec, conv);
                    print_extra = x0_body != body;
                }
            }
            if !print_extra {
                break;
            }
        }
        io.stdout.write_all(separator.as_bytes())?;
        i += 1.0;
    }
    io.stdout.write_all(b"\n")
}

/// seq_fast(): decimal string increment from a to b inclusive, step n.
/// `inf` end loops forever. Returns Ok(false) when b < a (GNU falls
/// through to the long-double path, which also prints nothing there).
fn seq_fast(io: &mut Io, a: &str, b: &str, step: u64, separator: &str) -> std::io::Result<bool> {
    let inf = b == "inf";
    let mut num = trim_leading_zeros(a).as_bytes().to_vec();
    let end = trim_leading_zeros(b).as_bytes().to_vec();
    if !inf && cmp_digits(&num, &end) == std::cmp::Ordering::Greater {
        return Ok(false);
    }
    let mut out = Vec::new();
    out.extend_from_slice(&num);
    loop {
        for _ in 0..step {
            incr(&mut num);
        }
        if !inf && cmp_digits(&num, &end) == std::cmp::Ordering::Greater {
            break;
        }
        out.extend_from_slice(separator.as_bytes());
        out.extend_from_slice(&num);
        if inf && out.len() >= 1 << 20 {
            io.stdout.write_all(&out)?;
            out.clear();
        }
    }
    out.push(b'\n');
    io.stdout.write_all(&out)?;
    Ok(true)
}

fn trim_leading_zeros(s: &str) -> &str {
    let t = s.trim_start_matches('0');
    if t.is_empty() {
        "0"
    } else {
        t
    }
}

fn cmp_digits(a: &[u8], b: &[u8]) -> std::cmp::Ordering {
    a.len().cmp(&b.len()).then_with(|| a.cmp(b))
}

/// Increment a decimal digit string in place (seq.c incr()).
fn incr(num: &mut Vec<u8>) {
    for b in num.iter_mut().rev() {
        if *b < b'9' {
            *b += 1;
            return;
        }
        *b = b'0';
    }
    num.insert(0, b'1');
}

fn all_digits(s: &str) -> bool {
    !s.is_empty() && s.bytes().all(|b| b.is_ascii_digit())
}

struct ScanErr<'a> {
    text: &'a str,
    nan: bool,
}

pub fn seq_cmd(args: &[OsString], io: &mut Io, _ctx: &Ctx) -> CmdResult {
    let strs: Vec<String> = args
        .iter()
        .map(|a| a.to_string_lossy().into_owned())
        .collect();
    let mut format: Option<String> = None;
    let mut separator = "\n".to_string();
    let mut equal_width = false;
    let mut idx = 0usize;
    // seq.c main loop: options until first non-option, "--", or an
    // operand starting with "-." or "-<digit>" (negative numbers).
    while idx < strs.len() {
        let arg = &strs[idx];
        let neg_operand = arg.starts_with('-')
            && arg.len() > 1
            && (arg.as_bytes()[1] == b'.' || arg.as_bytes()[1].is_ascii_digit());
        if neg_operand || !arg.starts_with('-') {
            break;
        }
        if arg == "--" {
            idx += 1;
            break;
        }
        if let Some(long) = arg.strip_prefix("--") {
            let (name, inline) = match long.split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (long.to_string(), None),
            };
            match name.as_str() {
                "format" => {
                    let v = match take_arg(inline, &strs, &mut idx) {
                        Some(v) => v,
                        None => {
                            let _ =
                                usage_error(io, "seq", "option '--format' requires an argument");
                            return Ok(1);
                        }
                    };
                    format = Some(v);
                }
                "separator" => {
                    let v = match take_arg(inline, &strs, &mut idx) {
                        Some(v) => v,
                        None => {
                            let _ =
                                usage_error(io, "seq", "option '--separator' requires an argument");
                            return Ok(1);
                        }
                    };
                    separator = v;
                }
                "equal-width" => equal_width = true,
                "help" | "version" => return Ok(0),
                _ => {
                    let _ = usage_error(io, "seq", &format!("unrecognized option '{arg}'"));
                    return Ok(1);
                }
            }
            idx += 1;
            continue;
        }
        // short option cluster
        let chars: Vec<char> = arg.chars().skip(1).collect();
        let mut ci = 0usize;
        let mut consumed_next = false;
        while ci < chars.len() {
            let c = chars[ci];
            match c {
                'f' | 's' => {
                    let rest: String = chars[ci + 1..].iter().collect();
                    let (v, ok) = if !rest.is_empty() {
                        (rest, true)
                    } else {
                        match strs.get(idx + 1) {
                            Some(v) => {
                                consumed_next = true;
                                (v.clone(), true)
                            }
                            None => (String::new(), false),
                        }
                    };
                    if !ok {
                        let _ = usage_error(
                            io,
                            "seq",
                            &format!("option requires an argument -- '{c}'"),
                        );
                        return Ok(1);
                    }
                    if c == 'f' {
                        format = Some(v);
                    } else {
                        separator = v;
                    }
                    break; // rest of cluster was the value
                }
                'w' => {
                    equal_width = true;
                    ci += 1;
                }
                _ => {
                    let _ = usage_error(io, "seq", &format!("invalid option -- '{c}'"));
                    return Ok(1);
                }
            }
        }
        idx += if consumed_next { 2 } else { 1 };
    }
    let operands = &strs[idx..];
    if operands.is_empty() {
        let _ = usage_error(io, "seq", "missing operand");
        return Ok(1);
    }
    if operands.len() > 3 {
        let _ = usage_error(io, "seq", &format!("extra operand '{}'", operands[3]));
        return Ok(1);
    }
    // ---- format validation (seq.c long_double_format call) ----
    if let Some(f) = &format {
        if let Err(msg) = parse_format(f) {
            let _ = writeln!(io.stderr, "seq: {msg}");
            return Ok(1);
        }
    }
    // ---- -w/-f conflict ----
    if format.is_some() && equal_width {
        let _ = usage_error(
            io,
            "seq",
            "format string may not be specified when printing equal width strings",
        );
        return Ok(1);
    }
    // ---- fast integer path (first attempt: digit-string operands) ----
    let step_ok = if operands.len() == 3 {
        all_digits(&operands[1])
            && operands[1]
                .parse::<u64>()
                .map(|v| v > 0 && v <= SEQ_FAST_STEP_LIMIT)
                .unwrap_or(false)
    } else {
        true
    };
    if operands.iter().all(|s| all_digits(s))
        && step_ok
        && !equal_width
        && format.is_none()
        && separator.len() == 1
    {
        let step: u64 = if operands.len() == 3 {
            operands[1].parse().unwrap()
        } else {
            1
        };
        let (a, b) = if operands.len() == 1 {
            ("1", operands[0].as_str())
        } else {
            (operands[0].as_str(), operands[operands.len() - 1].as_str())
        };
        seq_fast(io, a, b, step, &separator)?;
        return Ok(0);
    }
    // ---- operand scanning (long-double path) ----
    let mut first = Operand {
        value: 1.0,
        width: 1,
        precision: 0,
    };
    let mut step = Operand {
        value: 1.0,
        width: 1,
        precision: 0,
    };
    let mut oidx = idx;
    let scan = scan_operand(&strs[oidx]);
    let mut last = match scan {
        Ok(o) => o,
        Err(e) => return scan_error(io, &e),
    };
    oidx += 1;
    if oidx < strs.len() {
        first = last;
        last = match scan_operand(&strs[oidx]) {
            Ok(o) => o,
            Err(e) => return scan_error(io, &e),
        };
        oidx += 1;
        if oidx < strs.len() {
            step = last;
            if step.value == 0.0 {
                let _ = usage_error(
                    io,
                    "seq",
                    &format!("invalid Zero increment value: '{}'", strs[oidx - 1]),
                );
                return Ok(1);
            }
            last = match scan_operand(&strs[oidx]) {
                Ok(o) => o,
                Err(e) => return scan_error(io, &e),
            };
        }
    }
    // ---- second fast attempt: scientific-notation integers, inf end ----
    // Endpoints render through the exact decimal when possible: GNU prints
    // "%0.Lf" of the long double (seq.c lines 686-695), which is the plain
    // integer digits for these, while f64 loses them past its mantissa
    // (probed: `seq 1e23 1e23` — GNU 100000000000000000000000, f64
    // 99999999999999991611392).
    let op_texts: Vec<&str> = strs[idx..].iter().map(|s| s.as_str()).collect();
    let exact_ops: [Option<ExactDec>; 3] = match op_texts.len() {
        1 => [
            parse_exact_decimal("1"),
            parse_exact_decimal("1"),
            parse_exact_decimal(&op_texts[0]),
        ],
        2 => [
            parse_exact_decimal(&op_texts[0]),
            parse_exact_decimal("1"),
            parse_exact_decimal(&op_texts[1]),
        ],
        _ => [
            parse_exact_decimal(&op_texts[0]),
            parse_exact_decimal(&op_texts[1]),
            parse_exact_decimal(&op_texts[2]),
        ],
    };
    let exact_str = |d: &Option<ExactDec>| -> Option<String> {
        let d = d.as_ref()?;
        Some(if d.neg_zero {
            "-0".to_string()
        } else {
            d.mant.to_string()
        })
    };
    if first.precision == 0
        && step.precision == 0
        && last.precision == 0
        && first.value.is_finite()
        && first.value >= 0.0
        && last.value >= 0.0
        && step.value > 0.0
        && step.value <= SEQ_FAST_STEP_LIMIT as f64
        && !equal_width
        && format.is_none()
        && separator.len() == 1
    {
        let s1 = exact_str(&exact_ops[0]).unwrap_or_else(|| format!("{:.0}", first.value));
        let s2 = if last.value.is_finite() {
            exact_str(&exact_ops[2]).unwrap_or_else(|| format!("{:.0}", last.value))
        } else {
            "inf".to_string()
        };
        if !s1.starts_with('-') && !s2.starts_with('-') {
            if seq_fast(io, &s1, &s2, step.value as u64, &separator)? {
                return Ok(0);
            }
        }
    }
    // ---- exact decimal generation (uutils-borrowed fixed-point stepping) ----
    if format.is_none() {
        let (ft, st, lt) = match op_texts.len() {
            1 => ("1", "1", op_texts[0]),
            2 => (op_texts[0], "1", op_texts[1]),
            _ => (op_texts[0], op_texts[1], op_texts[2]),
        };
        if let Some(run) = try_exact_run((ft, st, lt), &first, &step, &last, equal_width) {
            run.print(io, &separator)?;
            return Ok(0);
        }
    }
    // ---- format resolution and printing ----
    let (prefix, spec, conv, suffix) = match &format {
        Some(f) => parse_format(f).unwrap(),
        None => {
            let f = default_format(&first, &step, &last, equal_width);
            let (p, s, c, x) = parse_format(&f).unwrap();
            (p, s, c, x)
        }
    };
    print_numbers(
        io,
        &spec,
        conv,
        &prefix,
        &suffix,
        first.value,
        step.value,
        last.value,
        &separator,
    )?;
    Ok(0)
}

fn scan_operand(s: &str) -> Result<Operand, ScanErr<'_>> {
    match strtold_full(s) {
        None => Err(ScanErr {
            text: s,
            nan: false,
        }),
        Some(v) if v.is_nan() => Err(ScanErr { text: s, nan: true }),
        Some(_) => scan_arg(s).map_err(|_| ScanErr {
            text: s,
            nan: false,
        }),
    }
}

fn scan_error(io: &mut Io, e: &ScanErr<'_>) -> CmdResult {
    let msg = if e.nan {
        format!("invalid 'not-a-number' argument: '{}'", e.text)
    } else {
        format!("invalid floating point argument: '{}'", e.text)
    };
    let _ = usage_error(io, "seq", &msg);
    Ok(1)
}

fn take_arg(inline: Option<String>, strs: &[String], idx: &mut usize) -> Option<String> {
    if inline.is_some() {
        return inline;
    }
    *idx += 1;
    strs.get(*idx).cloned()
}

#[cfg(test)]
mod tests {
    use super::*;
    use winux_core::test_support::{MemIo, ScratchCtx};

    fn run(args: &[&str], stdin: &str) -> (u32, String, String) {
        let sc = ScratchCtx::new("seq");
        let mut io = MemIo::new(stdin);
        let ctx = sc.ctx();
        let owned: Vec<OsString> = args.iter().map(Into::into).collect();
        let r = seq_cmd(&owned, &mut io.split(), &ctx).unwrap();
        (r, io.out(), io.err())
    }

    #[test]
    fn basic_sequences() {
        assert_eq!(run(&["5"], ""), (0, "1\n2\n3\n4\n5\n".into(), "".into()));
        assert_eq!(run(&["2", "5"], ""), (0, "2\n3\n4\n5\n".into(), "".into()));
        assert_eq!(
            run(&["1", "2", "10"], ""),
            (0, "1\n3\n5\n7\n9\n".into(), "".into())
        );
        assert_eq!(
            run(&["10", "-2", "1"], ""),
            (0, "10\n8\n6\n4\n2\n".into(), "".into())
        );
        assert_eq!(run(&["-1"], ""), (0, "".into(), "".into()));
        assert_eq!(run(&["-1", "-5"], ""), (0, "".into(), "".into()));
        // from 1 to 0 is an empty range (GNU probed)
        assert_eq!(run(&["0"], ""), (0, "".into(), "".into()));
        assert_eq!(run(&["3", "1"], ""), (0, "".into(), "".into()));
        assert_eq!(run(&["--", "-3", "1"], "").1, "-3\n-2\n-1\n0\n1\n");
    }

    #[test]
    fn big_integers_fast_path() {
        let (r, out, _) = run(&["100000000000000000000", "100000000000000000010"], "");
        assert_eq!(r, 0);
        assert!(out.starts_with("100000000000000000000\n100000000000000000001\n"));
        assert!(out.ends_with("100000000000000000010\n"));
        // leading zeros trimmed
        let (r, out, _) = run(&["09", "10"], "");
        assert_eq!(r, 0);
        assert_eq!(out, "9\n10\n");
    }

    #[test]
    fn step_200_limit() {
        // step 200 stays on the fast path (exact big numbers)
        let (_, out, _) = run(
            &["1000000000000000000000", "200", "1000000000000000002200"],
            "",
        );
        assert!(out.starts_with("1000000000000000000000\n"));
        assert!(out.contains("1000000000000000002200\n"));
        // step 201 goes float: still fine for small values
        assert!(!run(&["1", "201", "1000"], "").1.is_empty());
    }

    #[test]
    fn width_and_separator() {
        assert_eq!(run(&["-w", "1", "3", "10"], "").1, "01\n04\n07\n10\n");
        assert_eq!(run(&["-w", "8", "10"], "").1, "08\n09\n10\n");
        assert_eq!(run(&["-s,", "1", "5"], "").1, "1,2,3,4,5\n");
        assert_eq!(run(&["-s", "--", "1", "3"], "").1, "1--2--3\n");
        assert_eq!(run(&["-s-", "1", "3"], "").1, "1-2-3\n");
        assert_eq!(run(&["--separator=:", "1", "3"], "").1, "1:2:3\n");
    }

    #[test]
    fn float_sequences() {
        assert_eq!(
            run(&["1.5", "0.2", "2.5"], "").1,
            "1.5\n1.7\n1.9\n2.1\n2.3\n2.5\n"
        );
        assert_eq!(run(&["0", "-0.1", "-0.3"], "").1, "0.0\n-0.1\n-0.2\n-0.3\n");
        assert_eq!(run(&["1", "0.5", "2"], "").1, "1.0\n1.5\n2.0\n");
        assert_eq!(
            run(&["1.0", "0.25", "2"], "").1,
            "1.00\n1.25\n1.50\n1.75\n2.00\n"
        );
        assert_eq!(run(&["0.0", "3"], "").1, "0.0\n1.0\n2.0\n3.0\n");
        // GNU's rounding fixup: extra number past last prints
        assert_eq!(
            run(&["0", "0.000001", "0.000003"], "").1,
            "0.000000\n0.000001\n0.000002\n0.000003\n"
        );
    }

    #[test]
    fn exact_decimal_long_fractions() {
        // audit case (PR #1562 case5, DOCS/2.0-uutils-audit.md §4.1): the
        // f64 engine rounded the 19-digit first operand to 1.0
        assert_eq!(
            run(&["0.9999999999999999999", "1.0000000000000000002"], "").1,
            "0.9999999999999999999\n"
        );
        assert_eq!(
            run(
                &["-w", "0.9999999999999999999", "1.0000000000000000002"],
                ""
            )
            .1,
            "0.9999999999999999999\n"
        );
        // GNU 9.4 probed 4 lines; f64 stepped below its ulp and looped
        // forever printing 1.0000000000000000000
        assert_eq!(
            run(
                &[
                    "0.9999999999999999999",
                    "0.0000000000000000001",
                    "1.0000000000000000002"
                ],
                ""
            )
            .1,
            "0.9999999999999999999\n1.0000000000000000000\n1.0000000000000000001\n1.0000000000000000002\n"
        );
        // 20 significant digits: GNU long double parses to 1.0, so the
        // parity guard hands the shape back to the float path (probed)
        assert_eq!(
            run(&["0.99999999999999999999", "2"], "").1,
            "1.00000000000000000000\n2.00000000000000000000\n"
        );
    }

    #[test]
    fn exact_decimal_no_drift() {
        // 1000 steps of 0.001: every line is the exact decimal
        let (_, out, _) = run(&["0", "0.001", "1"], "");
        let lines: Vec<&str> = out.lines().collect();
        assert_eq!(lines.len(), 1001);
        assert_eq!(lines[0], "0.000");
        assert_eq!(lines[1], "0.001");
        assert_eq!(lines[999], "0.999");
        assert_eq!(lines[1000], "1.000");
        // 18-digit grid, 10 steps (GNU probed byte-for-byte)
        assert_eq!(
            run(
                &[
                    "0.000000000000000001",
                    "0.000000000000000001",
                    "0.00000000000000001"
                ],
                ""
            )
            .1,
            "0.000000000000000001\n0.000000000000000002\n0.000000000000000003\n0.000000000000000004\n0.000000000000000005\n0.000000000000000006\n0.000000000000000007\n0.000000000000000008\n0.000000000000000009\n0.000000000000000010\n"
        );
        // 19-digit grid across an integer boundary (sub-f64-ulp steps used
        // to loop forever printing 0.0000000000000000000)
        assert_eq!(
            run(
                &["0", "0.0000000000000000001", "0.0000000000000000003"],
                ""
            )
            .1,
            "0.0000000000000000000\n0.0000000000000000001\n0.0000000000000000002\n0.0000000000000000003\n"
        );
        // scientific integers beyond the f64 mantissa (GNU %0.Lf probed)
        assert_eq!(run(&["1e23", "1e23"], "").1, "100000000000000000000000\n");
        assert_eq!(run(&["1e19", "1e19"], "").1, "10000000000000000000\n");
        // negative zero survives normalization (GNU probed)
        assert_eq!(run(&["-0.0", "0.2", "0.4"], "").1, "-0.0\n0.2\n0.4\n");
        assert_eq!(run(&["-0", "0"], "").1, "-0\n");
        // exact path keeps -w and custom separators
        assert_eq!(
            run(
                &["-w", "0.9999999999999999999", "1.0000000000000000002"],
                ""
            )
            .1,
            "0.9999999999999999999\n"
        );
        assert_eq!(
            run(
                &[
                    "-s,",
                    "0",
                    "0.0000000000000000001",
                    "0.0000000000000000003"
                ],
                ""
            )
            .1,
            "0.0000000000000000000,0.0000000000000000001,0.0000000000000000002,0.0000000000000000003\n"
        );
    }

    #[test]
    fn format_flags() {
        assert_eq!(run(&["-f", "%.2f", "1", "3"], "").1, "1.00\n2.00\n3.00\n");
        assert_eq!(
            run(&["-f", "%5.1f", "1", "3"], "").1,
            "  1.0\n  2.0\n  3.0\n"
        );
        assert_eq!(
            run(&["-f", "%g", "1.5", "0.5", "3"], "").1,
            "1.5\n2\n2.5\n3\n"
        );
        assert_eq!(
            run(&["-f", "%.3g", "1.23456", "1", "1.23456"], "").1,
            "1.23\n"
        );
        assert_eq!(run(&["-f", "x%g", "1", "2"], "").1, "x1\nx2\n");
        assert_eq!(run(&["-f", "%Lg", "1.5", "2.5"], "").1, "1.5\n2.5\n");
        assert_eq!(run(&["-f", "%g ", "1", "2"], "").1, "1 \n2 \n");
        assert_eq!(
            run(&["-f", "%08.3f", "1", "3"], "").1,
            "0001.000\n0002.000\n0003.000\n"
        );
        assert_eq!(
            run(&["-f", "%-8.2f|", "1", "2"], "").1,
            "1.00    |\n2.00    |\n"
        );
        assert_eq!(run(&["-f", "%+.1f", "1", "2"], "").1, "+1.0\n+2.0\n");
        assert_eq!(
            run(&["-f", "% f", "1", "2"], "").1,
            " 1.000000\n 2.000000\n"
        );
        assert_eq!(run(&["-f", "%#.0f", "1", "2"], "").1, "1.\n2.\n");
        assert_eq!(
            run(&["-f", "%.0e", "1", "3"], "").1,
            "1e+00\n2e+00\n3e+00\n"
        );
        assert_eq!(
            run(&["-f", "%E", "1234", "1", "1235"], "").1,
            "1.234000E+03\n1.235000E+03\n"
        );
        assert_eq!(
            run(&["-f", "%.3G", "1234567", "1", "1234570"], "").1,
            "1.23E+06\n1.23E+06\n1.23E+06\n1.23E+06\n"
        );
        assert_eq!(run(&["-f", "%.1a", "1", "2"], "").1, "0x8.0p-3\n0x8.0p-2\n");
        assert_eq!(run(&["-f", "%a", "1", "2"], "").1, "0x8p-3\n0x8p-2\n");
        assert_eq!(run(&["-f", "%A", "1.5", "2.5"], "").1, "0XCP-3\n0XAP-2\n");
        // bare %% has no % directive either (GNU probed via '%%g')
        let (r, _, e) = run(&["-f", "%%", "1", "2"], "");
        assert_eq!(r, 1);
        assert!(e.contains("has no % directive"));
    }

    #[test]
    fn width_computation() {
        assert_eq!(run(&["-w", "0.1", "0.2", "0.3"], "").1, "0.1\n0.3\n");
        assert_eq!(
            run(&["-w", "1", "0.5", "2.5"], "").1,
            "1.0\n1.5\n2.0\n2.5\n"
        );
        assert_eq!(
            run(&["-w", "9", "0.5", "11"], "").1,
            "09.0\n09.5\n10.0\n10.5\n11.0\n"
        );
        assert_eq!(
            run(&["-w", "1e-2", "0.01", "3e-2"], "").1,
            "0.01\n0.02\n0.03\n"
        );
    }

    #[test]
    fn hex_and_odd_parse() {
        assert_eq!(run(&["0x1p3"], "").1.split('\n').count(), 9); // 1..=8
        assert_eq!(run(&["0x1.8p3"], "").1.split('\n').count(), 13); // 1..=12
        assert_eq!(run(&["1.", "2"], "").1, "1\n2\n");
        assert_eq!(run(&[".5", "2"], "").1, "0.5\n1.5\n");
        assert_eq!(run(&["+2", "+1", "+6"], "").1, "2\n3\n4\n5\n6\n");
        assert_eq!(run(&["1e1", "1e1"], "").1, "10\n");
    }

    #[test]
    fn errors() {
        let (r, _, e) = run(&[], "");
        assert_eq!(r, 1);
        assert!(e.contains("missing operand"));
        let (r, _, e) = run(&["1", "2", "3", "4"], "");
        assert_eq!(r, 1);
        assert!(e.contains("extra operand '4'"));
        let (r, _, e) = run(&["abc"], "");
        assert_eq!(r, 1);
        assert!(e.contains("invalid floating point argument: 'abc'"));
        let (r, _, e) = run(&["nan"], "");
        assert_eq!(r, 1);
        assert!(e.contains("not-a-number"));
        let (r, _, e) = run(&["1", "0", "3"], "");
        assert_eq!(r, 1);
        assert!(e.contains("invalid Zero increment value: '0'"));
        let (r, _, e) = run(&["-w", "-f", "%.2f", "1", "2"], "");
        assert_eq!(r, 1);
        assert!(e.contains("format string may not be specified"));
        let (r, _, e) = run(&["-f", "abc", "1", "3"], "");
        assert_eq!(r, 1);
        assert!(e.contains("has no % directive"));
        let (r, _, e) = run(&["-f", "%d", "1", "3"], "");
        assert_eq!(r, 1);
        assert!(e.contains("has unknown %d directive"));
        let (r, _, e) = run(&["-f", "%%g", "1", "2"], "");
        assert_eq!(r, 1);
        assert!(e.contains("has no % directive"));
        let (r, _, e) = run(&["-f", "%f%g", "1", "2"], "");
        assert_eq!(r, 1);
        assert!(e.contains("has too many % directives"));
        let (r, _, e) = run(&["2x"], "");
        assert_eq!(r, 1);
        assert!(e.contains("invalid floating point argument: '2x'"));
        let (r, _, e) = run(&["1", "--", "-2"], "");
        assert_eq!(r, 1);
        assert!(e.contains("invalid floating point argument: '--'"));
        let (r, _, e) = run(&["-s"], "");
        assert_eq!(r, 1);
        assert!(e.contains("option requires an argument -- 's'"));
        let (r, _, e) = run(&["--bogus"], "");
        assert_eq!(r, 1);
        assert!(e.contains("unrecognized option '--bogus'"));
        let (r, _, e) = run(&["-q"], "");
        assert_eq!(r, 1);
        assert!(e.contains("invalid option -- 'q'"));
        assert_eq!(run(&["--help"], "").0, 0);
        assert_eq!(run(&["--version"], "").0, 0);
    }
}
